const payload = $input.first().json.body || $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.trafficLogs = staticData.trafficLogs || [];

const entry = {
  action: payload.action || 'page_view',
  path: payload.path || '/',
  user_email: payload.user_email || 'anonymous',
  role: payload.role || 'visitor',
  user_agent: payload.user_agent || '',
  timestamp: payload.timestamp || new Date().toISOString()
};

staticData.trafficLogs.push(entry);

// Conserver seulement les logs des dernières 24 heures (max 2000 entrées)
const cutoff = Date.now() - (24 * 60 * 60 * 1000);
staticData.trafficLogs = staticData.trafficLogs
  .filter(e => new Date(e.timestamp).getTime() > cutoff)
  .slice(-2000);

return [{
  json: {
    status: 'traffic_recorded',
    trackedAction: entry.action,
    totalBuffered: staticData.trafficLogs.length,
    entry
  }
}];

// 1. Récupération des observations Supabase
const rawInputs = $input.all();
let observations = [];

if (rawInputs.length > 0) {
  if (Array.isArray(rawInputs[0].json)) {
    observations = rawInputs[0].json;
  } else if (rawInputs[0].json && typeof rawInputs[0].json === 'object') {
    observations = rawInputs.map(item => item.json).filter(Boolean);
  }
}

// 2. Récupération des logs de trafic sur les 4 dernières heures depuis staticData
const staticData = $getWorkflowStaticData('global');
const trafficLogs = staticData.trafficLogs || [];
const fourHoursAgo = Date.now() - (4 * 60 * 60 * 1000);

const recentTraffic = trafficLogs.filter(e => new Date(e.timestamp).getTime() >= fourHoursAgo);

// Visiteurs uniques (basé sur IP/user_agent ou email)
const uniqueVisitorsSet = new Set(recentTraffic.map(e => e.user_email !== 'anonymous' ? e.user_email : (e.user_agent || 'unknown')));
const uniqueVisitors = uniqueVisitorsSet.size;

// Connexions enregistrées
const loginCount = recentTraffic.filter(e => e.action === 'login').length;

// Métriques de collecte
const collectCount = observations.length;
const marketsSet = new Set(observations.map(o => (o.markets && o.markets.name) || o.market_id).filter(Boolean));
const marketsCovered = marketsSet.size;

// Génération de l'horodatage en heure locale Bujumbura (UTC+2)
const nowStr = new Date().toLocaleString('fr-FR', { timeZone: 'Africa/Bujumbura' });
const startWindowStr = new Date(fourHoursAgo).toLocaleString('fr-FR', { timeZone: 'Africa/Bujumbura' });

// Construction du contenu dynamique selon présence ou absence de collectes
let bodyContentHtml = '';

if (collectCount === 0) {
  // Condition 0 collecte : Mention exacte obligatoire bien visible
  bodyContentHtml = `
    <div style="background-color:#fef2f2;border:2px solid #f87171;border-radius:10px;padding:24px;text-align:center;margin:20px 0;">
      <div style="font-size:36px;margin-bottom:12px;">⚠️</div>
      <h2 style="color:#991b1b;font-size:18px;font-weight:800;margin:0 0 10px 0;">
        Aucune activité ni collecte de prix n'a été effectuée durant les 4 dernières heures.
      </h2>
      <p style="color:#7f1d1d;font-size:14px;margin:0;line-height:20px;">
        Aucune nouvelle observation de prix n'a été transmise par les agents de terrain entre <strong>${startWindowStr}</strong> et <strong>${nowStr}</strong>.
      </p>
    </div>
    <div style="background-color:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;padding:16px;margin-top:16px;">
      <h4 style="margin:0 0 8px 0;font-size:13px;color:#475569;text-transform:uppercase;">Points d'attention :</h4>
      <ul style="margin:0;padding-left:20px;font-size:13px;color:#64748b;line-height:20px;">
        <li>Vérifier la connectivité réseau des équipes de terrain.</li>
        <li>Confirmer si les marchés cibles étaient actifs sur ce créneau horaire.</li>
        <li>Vérifier que les files d'attente hors-ligne (PWA/Capacitor) ont bien été synchronisées.</li>
      </ul>
    </div>
  `;
} else {
  // Condition >= 1 collecte : Tableau récapitulatif détaillé
  const rowsHtml = observations.map((o, idx) => {
    const market = (o.markets && o.markets.name) || 'Marché non spécifié';
    const commune = (o.markets && o.markets.commune) || '-';
    const product = (o.products && o.products.name) || 'Produit';
    const price = Number(o.price || 0).toLocaleString('fr-FR');
    const unit = o.unit || 'kg';
    const variety = o.variety ? `(${o.variety})` : '';
    const time = o.observed_at ? new Date(o.observed_at).toLocaleTimeString('fr-FR', { timeZone: 'Africa/Bujumbura', hour: '2-digit', minute: '2-digit' }) : '-';
    const status = o.status || 'SYNCHRONISEE';
    const statusColor = status === 'VALIDEE' ? '#15803d' : '#0369a1';
    const statusBg = status === 'VALIDEE' ? '#dcfce7' : '#e0f2fe';
    const rowBg = idx % 2 === 0 ? '#ffffff' : '#f8fafc';

    return `
      <tr style="background-color:${rowBg};border-bottom:1px solid #e2e8f0;">
        <td style="padding:10px 12px;font-size:13px;font-weight:600;color:#0f172a;">${time}</td>
        <td style="padding:10px 12px;font-size:13px;color:#0f172a;font-weight:700;">${market} <span style="font-size:11px;color:#64748b;font-weight:normal;">(${commune})</span></td>
        <td style="padding:10px 12px;font-size:13px;color:#0f172a;">${product} <span style="font-size:11px;color:#64748b;">${variety}</span></td>
        <td style="padding:10px 12px;font-size:13px;font-weight:800;color:#047857;text-align:right;">${price} FBu / ${unit}</td>
        <td style="padding:10px 12px;text-align:center;"><span style="background-color:${statusBg};color:${statusColor};padding:3px 8px;border-radius:4px;font-size:11px;font-weight:700;">${status}</span></td>
      </tr>
    `;
  }).join('');

  bodyContentHtml = `
    <div style="margin:20px 0;">
      <h3 style="color:#0f172a;font-size:16px;font-weight:700;margin-bottom:12px;">
        📋 Observations recueillies (${collectCount})
      </h3>
      <div style="overflow-x:auto;border:1px solid #e2e8f0;border-radius:8px;">
        <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:13px;">
          <thead>
            <tr style="background-color:#0f172a;color:#ffffff;text-align:left;">
              <th style="padding:10px 12px;font-size:12px;text-transform:uppercase;">Heure</th>
              <th style="padding:10px 12px;font-size:12px;text-transform:uppercase;">Marché</th>
              <th style="padding:10px 12px;font-size:12px;text-transform:uppercase;">Produit</th>
              <th style="padding:10px 12px;font-size:12px;text-transform:uppercase;text-align:right;">Prix</th>
              <th style="padding:10px 12px;font-size:12px;text-transform:uppercase;text-align:center;">Statut</th>
            </tr>
          </thead>
          <tbody>
            ${rowsHtml}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

const fullHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Rapport d'activité Burundi Food Price</title>
</head>
<body style="margin:0;padding:0;background-color:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f1f5f9;padding:24px 12px;">
    <tr>
      <td align="center">
        <table width="100%" cellpadding="0" cellspacing="0" style="max-width:680px;background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 6px -1px rgba(0,0,0,0.1);border:1px solid #e2e8f0;">
          <!-- En-tête -->
          <tr>
            <td style="background:linear-gradient(135deg, #1e293b 0%, #0f172a 100%);padding:24px;text-align:left;">
              <table width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td>
                    <span style="display:inline-block;background-color:#059669;color:#ffffff;font-size:11px;font-weight:700;letter-spacing:0.5px;padding:4px 10px;border-radius:9999px;text-transform:uppercase;">Cycle Automatique 4H</span>
                    <h1 style="margin:8px 0 4px 0;color:#ffffff;font-size:22px;font-weight:800;">📊 Rapport d'activité BFP</h1>
                    <div style="color:#94a3b8;font-size:13px;">Période : ${startWindowStr} &rarr; ${nowStr} (Heure Bujumbura)</div>
                  </td>
                  <td align="right" valign="top">
                    <span style="font-size:36px;">📈</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <!-- Grille des Métriques Clés -->
          <tr>
            <td style="padding:20px 24px;background-color:#f8fafc;border-bottom:1px solid #e2e8f0;">
              <table width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td width="25%" style="padding:8px;text-align:center;">
                    <div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:700;">Collectes</div>
                    <div style="font-size:24px;font-weight:800;color:${collectCount > 0 ? '#047857' : '#dc2626'};margin-top:4px;">${collectCount}</div>
                  </td>
                  <td width="25%" style="padding:8px;text-align:center;border-left:1px solid #e2e8f0;">
                    <div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:700;">Marchés</div>
                    <div style="font-size:24px;font-weight:800;color:#0f172a;margin-top:4px;">${marketsCovered}</div>
                  </td>
                  <td width="25%" style="padding:8px;text-align:center;border-left:1px solid #e2e8f0;">
                    <div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:700;">Visiteurs</div>
                    <div style="font-size:24px;font-weight:800;color:#0284c7;margin-top:4px;">${uniqueVisitors}</div>
                  </td>
                  <td width="25%" style="padding:8px;text-align:center;border-left:1px solid #e2e8f0;">
                    <div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:700;">Connexions</div>
                    <div style="font-size:24px;font-weight:800;color:#7c3aed;margin-top:4px;">${loginCount}</div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <!-- Corps dynamique -->
          <tr>
            <td style="padding:24px;">
              ${bodyContentHtml}
            </td>
          </tr>
          <!-- Bouton Dashboard -->
          <tr>
            <td align="center" style="padding:0 24px 24px 24px;">
              <a href="https://burundifoodprice.bi/admin" style="display:inline-block;background-color:#0f172a;color:#ffffff;text-decoration:none;font-size:14px;font-weight:700;padding:12px 28px;border-radius:8px;text-align:center;">
                Consulter l'Observatoire National →
              </a>
            </td>
          </tr>
          <!-- Footer -->
          <tr>
            <td style="background-color:#f8fafc;padding:16px 24px;border-top:1px solid #e2e8f0;text-align:center;color:#94a3b8;font-size:12px;">
              Rapport périodique programmé toutes les 4 heures &bull; Burundi Food Price &bull; n8n
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
`;

return [{
  json: {
    subject: "📊 Rapport d'activité Burundi Food Price (Toutes les 4h)",
    toEmail: "quicksales.bi@gmail.com",
    html: fullHtml,
    collectCount,
    marketsCovered,
    uniqueVisitors,
    loginCount
  }
}];
